   197|  if (wordMatch) {
   198|    const a = parseFloat(wordMatch[1]);
   199|    const op = wordMatch[2];
   200|    const b = parseFloat(wordMatch[3]);
   201|    switch (op) {
   202|      case 'plus': case 'added to': return a + b;
   203|      case 'minus': case 'subtracted from': return op === 'subtracted from' ? b - a : a - b;
