   122|/**
   123| * Resolve a reference to actual context.
   124| * "fix this" → the latest error/screenshot mentioned in conversation.
   125| * "what is next?" → the current active task ledger.
   126| * "same as before" → the previous requirement.
   127| */
   128|export function resolveReference(
   129|  reference: { resolvesTo: string },
   130|  state: IVXConversationState,
   131|): { resolved: boolean; context: string; source: string } {
   132|  switch (reference.resolvesTo) {
   133|    case 'latest_error_or_screenshot': {
   134|      // Find the most recent message mentioning an error or screenshot
   135|      for (let i = state.messages.length - 1; i >= 0; i--) {
   136|        const msg = state.messages[i];
   137|        if (/\b(error|crash|fail|screenshot|broken|503|500|timeout)\b/i.test(msg.content)) {
   138|          return {
   139|            resolved: true,
   140|            context: msg.content.slice(0, 500),
   141|            source: `message ${msg.messageId} (${msg.timestamp})`,
   142|          };
   143|        }
   144|      }
   145|      return { resolved: false, context: '', source: 'no previous error found' };
   146|    }
   147|
   148|    case 'current_ledger': {
   149|      // Find the most recent task
   150|      const taskIds = [...state.taskLinks.values()];
   151|      if (taskIds.length > 0) {
   152|        const latestTaskId = taskIds[taskIds.length - 1];
   153|        return {
   154|          resolved: true,
   155|          context: `Current task: ${latestTaskId}`,
   156|          source: 'task ledger',
   157|        };
   158|      }
   159|      return { resolved: false, context: 'No active task', source: 'no task found' };
   160|    }
   161|
   162|    case 'previous_requirement': {
   163|      // Find the most recent user message before the current one
   164|      const userMessages = state.messages.filter((m) => m.role === 'user');
   165|      if (userMessages.length >= 2) {
   166|        const prevMessage = userMessages[userMessages.length - 2];
   167|        return {
   168|          resolved: true,
   169|          context: prevMessage.content.slice(0, 500),
   170|          source: `message ${prevMessage.messageId}`,
   171|        };
   172|      }
   173|      return { resolved: false, context: '', source: 'no previous requirement' };
   174|    }
   175|
   176|    case 'latest_entity': {
   177|      // Find the most recently mentioned entity
   178|      const entities = [...state.entities.values()];
   179|      if (entities.length > 0) {
   180|        const latest = entities[entities.length - 1];
   181|        return {
