    97|    'during', 'before', 'after', 'above', 'below', 'from', 'up', 'down',
    98|    'out', 'off', 'over', 'under', 'again', 'further', 'then', 'once',
    99|    'here', 'there', 'when', 'where', 'why', 'how', 'all', 'each', 'few',
   100|    'more', 'most', 'other', 'some', 'such', 'no', 'nor', 'not', 'only',
